function relu(arr) {
  return arr.map(v => v > 0 ? v : 0);
}

function softmax(arr) {
  const max = Math.max(...arr);
  const exp = arr.map(v => Math.exp(v - max));
  const sum = exp.reduce((a, b) => a + b, 0);
  return exp.map(v => v / sum);
}

// W shape: [in][out]  →  output[j] = b[j] + sum_k( x[k] * W[k][j] )
function layerForward(x, W, b) {
  return b.map((bi, j) =>
    bi + x.reduce((s, xi, k) => s + W[k][j] * xi, 0)
  );
}

function normalizeLandmarks(landmarks) {
  // landmarks: array of 21 objects with {x, y, z} — we use XY only
  const wx = landmarks[0].x;
  const wy = landmarks[0].y;
  const pts = landmarks.map(l => [l.x - wx, l.y - wy]);
  let maxVal = 0;
  for (const p of pts) {
    if (Math.abs(p[0]) > maxVal) maxVal = Math.abs(p[0]);
    if (Math.abs(p[1]) > maxVal) maxVal = Math.abs(p[1]);
  }
  if (maxVal < 1e-6) maxVal = 1e-6;
  const flat = [];
  for (const p of pts) { flat.push(p[0]/maxVal, p[1]/maxVal); }
  return flat; // length 42
}

function predictSign(landmarks) {
  let x = normalizeLandmarks(landmarks);
  const layers = SIGN_MODEL.layers;
  for (let i = 0; i < layers.length; i++) {
    x = layerForward(x, layers[i].W, layers[i].b);
    x = i < layers.length - 1 ? relu(x) : softmax(x);
  }
  let maxIdx = 0;
  for (let i = 1; i < x.length; i++) if (x[i] > x[maxIdx]) maxIdx = i;
  return {
    label:      SIGN_MODEL.classes[maxIdx],
    confidence: x[maxIdx],
    probs:      x
  };
}
